import assert from 'node:assert/strict';
import test from 'node:test';
import { parseNonNegativeCount } from './parse-count.mjs';

test('parses a non-negative count', () => {
  assert.equal(parseNonNegativeCount('3'), 3);
});

test('rejects negatives', () => {
  assert.throws(() => parseNonNegativeCount('-1'), RangeError);
});
